from math import pi
from typing import List
from qiskit import QuantumCircuit

def oracle(n: int, m: int, S: List[int]) -> QuantumCircuit:
    qc = QuantumCircuit(n, name="O")
    denom = 1 << m
    angle_unit = 2 * pi / denom
    for k in range(n):
        angle = angle_unit * (S[k] % denom)
        if angle != 0.0:
            qc.p(angle, k)
    return qc

# Alias as a common entry point name
def build_circuit(n: int, m: int, S: List[int]) -> QuantumCircuit:
    return oracle(n, m, S)

